-- Column constraint attributes are checked after the statement parses, so a
-- later syntax error is reported first, as PostgreSQL's analysis does.
CREATE TABLE t253 (a int NOT NULL DEFERRABLE, b int,);
CREATE TABLE t253 (a int CHECK (a > 0) INITIALLY DEFERRED, b int c);
CREATE TABLE t253 (a int UNIQUE ENFORCED, b int REFERENCES nope(x) DEFERRABLE NOT DEFERRABLE);
CREATE TABLE t253 (a int NOT NULL DEFERRABLE, b int UNIQUE NOT DEFERRABLE DEFERRABLE);
CREATE TABLE t253 (a int PRIMARY KEY INITIALLY DEFERRED NOT DEFERRABLE, b int NULL NOT ENFORCED);
CREATE TABLE t253 (a int DEFAULT 1 INITIALLY IMMEDIATE);
CREATE TABLE t253 (a int UNIQUE INITIALLY IMMEDIATE INITIALLY DEFERRED);
CREATE TABLE t253 (a int CHECK (a > 0) NOT ENFORCED ENFORCED);
CREATE TABLE t253 (a int NOT NULL DEFERRABLE) PARTITION BY;
ALTER TABLE nope253 ADD COLUMN a int NOT NULL DEFERRABLE;
ALTER TABLE nope253 ADD COLUMN a int NOT NULL DEFERRABLE garbage;
CREATE TABLE t253 (a int UNIQUE, b int REFERENCES t253(a) NOT ENFORCED, c int REFERENCES t253(a) DEFERRABLE INITIALLY DEFERRED);
SELECT conname, condeferrable, condeferred, conenforced FROM pg_constraint WHERE conrelid = 't253'::regclass ORDER BY conname;
